// O tipo de uma função: parâmetros à esquerda, seta, tipo de retorno à direita
let somar: (a: number, b: number) => number;
somar = (x, y) => x + y; // x e y já são number por contexto, sem anotar
console.log(somar(2, 3)); // 5

// Os nomes dos parâmetros dentro do tipo são documentação e não têm de coincidir
const subtrair: (minuendo: number, subtraendo: number) => number = (a, b) => a - b;
console.log(subtrair(9, 4)); // 5

// Sem valor de retorno, o tipo de retorno é void
const registar: (mensagem: string) => void = (m) => {
  console.log(m.toUpperCase());
};
registar("pronto"); // PRONTO

// Um tipo de função é um tipo de primeira classe: guarda-se num array como outro qualquer
const operacoes: ((a: number, b: number) => number)[] = [somar, subtrair];
console.log(operacoes[0](10, 5)); // 15

// @ts-expect-error o retorno declarado é number e a função devolve string
const errada: (a: number) => number = (a) => `valor ${a}`;
console.log(typeof errada); // "function"

// Com type alias: a forma mais direta e a mais usada
type Comparador = (a: number, b: number) => number;

const crescente: Comparador = (a, b) => a - b;
console.log([3, 1, 2].sort(crescente)); // [1, 2, 3]

// Com interface e call signature: a assinatura sem nome dentro das chavetas
interface Validador {
  (valor: string): boolean;
}

const naoVazio: Validador = (valor) => valor.trim().length > 0;
console.log(naoVazio("   ")); // false

// A interface compensa quando a função também transporta propriedades
interface Acumulador {
  (passo: number): number;
  total: number;
}

const acumular: Acumulador = Object.assign(
  (passo: number): number => {
    acumular.total += passo;
    return acumular.total;
  },
  { total: 0 }
);

console.log(acumular(5)); // 5
console.log(acumular(3)); // 8
console.log(acumular.total); // 8

// Um callback é apenas um parâmetro cujo tipo é um tipo de função
function repetir(vezes: number, acao: (indice: number) => void): void {
  for (let i = 0; i < vezes; i++) {
    acao(i);
  }
}

repetir(3, (i) => console.log(`passo ${i}`)); // passo 0, passo 1, passo 2

// @ts-expect-error o callback recebe um number, e não uma string
repetir(2, (texto: string) => console.log(texto));

// Dar nome ao tipo do callback deixa a assinatura legível
type AoFalhar = (erro: Error, tentativa: number) => void;

function comRetentativa(
  operacao: () => string,
  aoFalhar: AoFalhar,
  limite: number
): string | null {
  for (let tentativa = 1; tentativa <= limite; tentativa++) {
    try {
      return operacao();
    } catch (erro) {
      aoFalhar(erro instanceof Error ? erro : new Error(String(erro)), tentativa);
    }
  }
  return null;
}

const resultado = comRetentativa(
  () => "ok",
  (erro, tentativa) => console.log(tentativa, erro.message), // tipos vêm de AoFalhar
  3
);
console.log(resultado); // "ok"

type Ouvinte = (evento: string, hora: number) => void;

// Menos parâmetros é aceite: quem chama passa os dois na mesma, a função é que os ignora
const comAmbos: Ouvinte = (evento, hora) => console.log(evento, hora);
const soEvento: Ouvinte = (evento) => console.log(evento);
const semNada: Ouvinte = () => console.log("aconteceu alguma coisa");

comAmbos("clique", 1000);
soEvento("clique", 1000); // "clique"
semNada("clique", 1000); // "aconteceu alguma coisa"

// @ts-expect-error mais parâmetros do que os que quem chama vai passar
const aMais: Ouvinte = (evento, hora, origem) => console.log(evento, hora, origem);
console.log(typeof aMais); // "function"

// É esta regra que faz funcionar o padrão do map e do forEach
const nomes = ["ana", "bruno"];
console.log(nomes.map((n) => n.toUpperCase())); // ["ANA", "BRUNO"]
console.log(nomes.map((n, i) => `${i}: ${n}`)); // ["0: ana", "1: bruno"]

// Passar uma função já existente funciona por causa da mesma regra
console.log(["1", "2", "3"].map(Number)); // [1, 2, 3]

// E é também por causa dela que esta armadilha clássica compila sem queixas
console.log(["1", "2", "3"].map(parseInt)); // [1, NaN, NaN]

interface Animal {
  nome: string;
}
interface Cao extends Animal {
  raca: string;
}

// Retorno: devolver mais do que o prometido é seguro e é aceite
const produzCao: () => Animal = (): Cao => ({ nome: "Rex", raca: "Beagle" });
console.log(produzCao().nome); // "Rex"

// @ts-expect-error devolver menos do que o prometido falta ao contrato
const produzPouco: () => Cao = (): Animal => ({ nome: "Bolinhas" });
console.log(typeof produzPouco); // "function"

// Parâmetros: aceitar mais do que o contrato dá é seguro
type TrataCao = (c: Cao) => void;
const trataQualquerAnimal: TrataCao = (a: Animal) => console.log(a.nome);
trataQualquerAnimal({ nome: "Rex", raca: "Beagle" }); // "Rex"

// @ts-expect-error com strictFunctionTypes, exigir mais do que o contrato dá é recusado
const exigeDemais: (a: Animal) => void = (c: Cao) => console.log(c.raca);
console.log(typeof exigeDemais); // "function"

// A regra é mais frouxa em métodos declarados com sintaxe de método
interface Caixa {
  tratar(c: Animal): void;
}
const caixa: Caixa = {
  tratar(c: Cao) {
    console.log(c.raca);
  },
};
caixa.tratar({ nome: "Rex", raca: "Beagle" } as Cao); // "Beagle"

// O parâmetro this vem primeiro e não conta como argumento
function descrever(this: { nome: string }, prefixo: string): string {
  return `${prefixo} ${this.nome}`;
}

const pessoa = { nome: "Ana", descrever };
console.log(pessoa.descrever("Olá,")); // "Olá, Ana"

// @ts-expect-error o contexto passado ao call não tem a propriedade nome
console.log(descrever.call({ idade: 30 }, "Olá,"));

// Em métodos de interface funciona da mesma maneira
interface Botao {
  etiqueta: string;
  aoClicar(this: Botao, evento: string): void;
}

const guardar: Botao = {
  etiqueta: "Guardar",
  aoClicar(evento) {
    console.log(`${this.etiqueta}: ${evento}`); // this é Botao
  },
};

guardar.aoClicar("clique"); // "Guardar: clique"

// Arrancar o método do objeto perde o contexto, e o compilador apanha-o
const solta = guardar.aoClicar;
// @ts-expect-error sem objeto à esquerda, o this seria undefined
solta("clique");

// @ts-expect-error uma arrow function não tem this próprio, logo não pode declará-lo
const semSentido = (this: { nome: string }, prefixo: string) => prefixo;
console.log(typeof semSentido); // "function"

// Dentro de um método, a arrow herda o this e o tipo vem junto, sem gambiarras
interface Carrinho {
  total: number;
  precos: number[];
  somar(this: Carrinho): number;
}

const carrinho: Carrinho = {
  total: 0,
  precos: [10, 20, 5],
  somar() {
    this.precos.forEach((p) => {
      this.total += p; // this continua a ser Carrinho
    });
    return this.total;
  },
};

console.log(carrinho.somar()); // 35

// Com function, o this deixa de ser o objeto e o compilador recusa-se a adivinhar
interface Registo {
  prefixo: string;
  imprimir(this: Registo, linhas: string[]): void;
}

const registo: Registo = {
  prefixo: "log",
  imprimir(linhas) {
    linhas.forEach(function (linha) {
      // @ts-expect-error aqui o this é implicitamente any, proibido em modo strict
      console.log(this.prefixo, linha);
    });
  },
};

registo.imprimir(["arrancou"]);

