type Formatador = (valor: number) => string;

const euros: Formatador = (valor) => `${valor.toFixed(2)} €`;
const percentagem: Formatador = (valor) => `${(valor * 100).toFixed(1)}%`;

const formatadores: Formatador[] = [euros, percentagem];
for (const formatar of formatadores) {
  console.log(formatar(0.25)); // "0.25 €" e depois "25.0%"
}

interface Predicado {
  (valor: number): boolean;
}

const positivo: Predicado = (valor) => valor > 0;
console.log([-2, 3, 0, 7].filter(positivo)); // [3, 7]

// @ts-expect-error o Formatador tem de devolver string
const invalido: Formatador = (valor) => valor * 2;
console.log(typeof invalido); // "function"

type Teste = (valor: number) => boolean;
type Transformacao = (valor: number) => number;

function aplicarSe(
  valores: number[],
  teste: Teste,
  transformar: Transformacao
): number[] {
  const saida: number[] = [];
  for (const valor of valores) {
    saida.push(teste(valor) ? transformar(valor) : valor);
  }
  return saida;
}

console.log(
  aplicarSe(
    [1, 2, 3, 4],
    (v) => v % 2 === 0,
    (v) => v * 10
  )
); // [1, 20, 3, 40]

// @ts-expect-error o teste tem de devolver boolean, e não number
console.log(aplicarSe([1, 2], (v) => v, (v) => v));

function comAviso(
  valores: number[],
  teste: Teste,
  aoAceitar: (valor: number, indice: number) => void
): void {
  valores.forEach((valor, indice) => {
    if (teste(valor)) {
      aoAceitar(valor, indice);
    }
  });
}

comAviso(
  [5, 12, 8],
  (v) => v > 6,
  (v) => console.log(`aceite: ${v}`) // ignora o índice, e isso é permitido
); // "aceite: 12" e depois "aceite: 8"

type Ouvinte = (evento: string, dados: string, hora: number) => void;

const ouvintes: Ouvinte[] = [];

function subscrever(ouvinte: Ouvinte): void {
  ouvintes.push(ouvinte);
}

function emitir(evento: string, dados: string): void {
  const hora = 1700000000000;
  for (const ouvinte of ouvintes) {
    ouvinte(evento, dados, hora);
  }
}

subscrever(() => console.log("aconteceu alguma coisa"));
subscrever((evento) => console.log(evento));
subscrever((evento, dados) => console.log(evento, dados));
subscrever((evento, dados, hora) => console.log(evento, dados, hora));

emitir("guardar", "id=7");
// "aconteceu alguma coisa"
// "guardar"
// "guardar id=7"
// "guardar id=7 1700000000000"

// @ts-expect-error quatro parâmetros e quem emite só passa três
subscrever((evento, dados, hora, origem) =>
  console.log(evento, dados, hora, origem)
);

interface Cronometro {
  etiqueta: string;
  marcas: number[];
  marcar(this: Cronometro, ms: number): void;
  total(this: Cronometro): number;
  resumo(this: Cronometro): string;
}

const cronometro: Cronometro = {
  etiqueta: "arranque",
  marcas: [],
  marcar(ms) {
    this.marcas.push(ms);
  },
  total() {
    let soma = 0;
    this.marcas.forEach((m) => {
      soma += m; // a arrow herda o this e o seu tipo
    });
    return soma;
  },
  resumo() {
    return `${this.etiqueta}: ${this.marcas.length} marcas, ${this.total()} ms`;
  },
};

cronometro.marcar(120);
cronometro.marcar(80);
console.log(cronometro.resumo()); // "arranque: 2 marcas, 200 ms"

// bind fixa o contexto e devolve uma função segura de passar por aí
const marcarLigado = cronometro.marcar.bind(cronometro);
marcarLigado(50);
console.log(cronometro.resumo()); // "arranque: 3 marcas, 250 ms"

// Nunca chamada: existe só para mostrar os dois erros que o this apanha
function demonstrarErros(): void {
  // @ts-expect-error o contexto passado não tem marcas nem os métodos de Cronometro
  cronometro.resumo.call({ etiqueta: "outro" });

  const solto = cronometro.marcar;
  // @ts-expect-error arrancado do objeto, o this seria undefined
  solto(50);
}

console.log(typeof demonstrarErros); // "function"
